Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>

using namespace std;

struct Node {
    int row, col, dist;
};

const int dx[4] = {-1, 0, 1, 0};
const int dy[4] = {0, -1, 0, 1};
queue<Node> q;
char s[15];
int n, n1, m, lim, tot, p;
int a[11][11], b[11][11], d0[11][11], f[202][202], d[202][202], w[202], h[202], g[203];
bool t, flag, ok[12][12], okb[12][12];

void search(int x, int z) {
    if (x == n + 1) {
        p = z;
        flag = true;
        return;
    }
    int temp = n + 2;
    for (int y = 0; y <= n + 1; ++y) {
        if (d[x][y] < f[x][y]) {
            temp = min(temp, h[y]);
            if (h[x] == h[y] + 1) {
                w[++tot] = y;
                search(y, min(z, f[x][y] - d[x][y]));
                if (!t || flag) return;
                w[tot--] = 0;
            }
        }
        if (d[y][x] > 0) {
            temp = min(temp, h[y]);
            if (h[x] == h[y] + 1) {
                w[++tot] = -y;
                search(y, min(z, d[y][x]));
                if (!t || flag) return;
                w[tot--] = 0;
            }
        }
    }
    if (temp + 1 != h[x]) {
        --g[h[x]];
        if (g[h[x]] == 0) t = false;
        h[x] = temp + 1;
        ++g[h[x]];
    }
}

bool improvable() {
    flag = false;
    p = n1;
    tot = 0;
    w[0] = 0;
    search(0, n1);
    return flag;
}

void improve() {
    for (int x = 1; x <= tot; ++x) {
        if (w[x] > 0)
            d[abs(w[x - 1])][w[x]] += p;
        else
            d[-w[x]][abs(w[x - 1])] -= p;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m_input, lim_input;
    cin >> m_input >> lim_input;
    m = m_input;
    lim = lim_input;
    for (int i = 1; i <= m; ++i) {
        cin >> s + 1;
        for (int j = 1; j <= m; ++j) {
            if (s[j] == 'Z') {
                Node he = {i, j, 0};
                q.push(he);
            } else if (s[j] != 'Y') {
                ok[i][j] = true;
                d0[i][j] = lim;
                int k = s[j] - '0';
                if (k > 0) {
                    a[i][j] = ++n;
                    f[0][n] = k;
                    n1 += k;
                }
            }
        }
    }
    memcpy(okb, ok, sizeof(ok));
    for (int i = 1; i <= m; ++i) {
        cin >> s + 1;
        for (int j = 1; j <= m; ++j) {
            if (s[j] == 'Z' || s[j] == 'Y') continue;
            int k = s[j] - '0';
            if (k > 0) {
                b[i][j] = ++n;
                f[n][m * m + 1] = k;
            }
        }
    }
    if (n != m * m) {
        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= m; ++j) {
                if (b[i][j] > 0) {
                    int k = b[i][j];
                    f[k][n + 1] = f[k][m * m + 1];
                    f[k][m * m + 1] = 0;
                }
            }
        }
    }
    while (!q.empty()) {
        Node he = q.front(); q.pop();
        int i = he.row, j = he.col;
        d0[i][j] = he.dist;
        for (int k = 0; k < 4; ++k) {
            int ni = i + dx[k], nj = j + dy[k];
            if (ok[ni][nj]) {
                Node e = {ni, nj, he.dist + 1};
                q.push(e);
                ok[ni][nj] = false;
            }
        }
    }
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i][j] == 0) continue;
            memcpy(ok, okb, sizeof(okb));
            ok[i][j] = false;
            Node he = {i, j, 0};
            q.push(he);
            while (!q.empty()) {
                Node he = q.front(); q.pop();
                int x = he.row, y = he.col;
                if (b[x][y] > 0 && he.dist <= d0[x][y]) {
                    f[a[i][j]][b[x][y]] = n1;
                }
                if (he.dist + 1 > lim || he.dist >= d0[x][y]) continue;
                for (int k = 0; k < 4; ++k) {
                    int nx = x + dx[k], ny = y + dy[k];
                    if (ok[nx][ny]) {
                        Node e = {nx, ny, he.dist + 1};
                        q.push(e);
                        ok[nx][ny] = false;
                    }
                }
            }
        }
    }
    g[0] = n + 2;
    t = true;
    while (t && h[0] <= n + 2) {
        while (improvable()) {
            improve();
        }
    }
    int ans = 0;
    for (int i = 1; i <= n; ++i) {
        ans += d[i][n + 1];
    }
    cout << ans << "\n";
    return 0;
}
